// Order-18 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the direct form.
module iir18_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r0;
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] y2;
  wire [31:0] acc = 25*x + r0 + ((9*y)>>4) + ((5*y2)>>4);
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r0<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; r9<=0; r10<=0; r11<=0; r12<=0; r13<=0; r14<=0; r15<=0; r16<=0; r17<=0; r18<=0; end
    else begin
      y <= acc[15:0];
      y2 <= y;
      r0<=(26*x + r1) & 16'hFFFF; r1<=(46*x + r2) & 16'hFFFF;
      r2<=(49*x + r3) & 16'hFFFF; r3<=(16*x + r4) & 16'hFFFF;
      r4<=(8*x + r5) & 16'hFFFF; r5<=(15*x + r6) & 16'hFFFF;
      r6<=(31*x + r7) & 16'hFFFF; r7<=(37*x + r8) & 16'hFFFF;
      r8<=(52*x + r9) & 16'hFFFF; r9<=(6*x + r10) & 16'hFFFF;
      r10<=(54*x + r11) & 16'hFFFF; r11<=(60*x + r12) & 16'hFFFF;
      r12<=(33*x + r13) & 16'hFFFF; r13<=(33*x + r14) & 16'hFFFF;
      r14<=(62*x + r15) & 16'hFFFF; r15<=(48*x + r16) & 16'hFFFF;
      r16<=(18*x + r17) & 16'hFFFF; r17<=(56*x + r18) & 16'hFFFF;
      r18<=(25*x) & 16'hFFFF;
    end
  end
endmodule
